# Our renderings (en | tr) of each masala's title and of the two schools' verbatim statements — "çeviri · hoca onayı bekliyor".
# n: (title_en, title_tr, kufa_en, kufa_tr, basra_en, basra_tr). Short and faithful; where the statement is compressed, less is said.
R = {
1: ("The derivation of ism (noun)", "İsim kelimesinin iştikakı",
    "Ism is derived from wasm, «mark».", "İsim, «alâmet» demek olan vesm'den türemiştir.",
    "Ism is derived from sumuww, «height».", "İsim, «yücelik» demek olan sümüvv'den türemiştir."),
2: ("The iʿrāb of the six nouns", "Esmâ-i sitte'nin i'râbı",
    "The six weak nouns (abūka, akhūka …) are declined from two places.", "Altı illetli isim (ebûke, ehûke …) iki yerden mu'reb olur.",
    "They are declined from one place; the wāw, alif and yāʾ are the letters of iʿrāb.", "Tek yerden mu'rebdir; vâv, elif ve yâ i'râb harfleridir."),
3: ("The iʿrāb of the dual and the sound plural", "Tesniye ve cem-i sâlimin i'râbı",
    "The alif, wāw and yāʾ of the dual and plural are iʿrāb, like the fatḥa, ḍamma and kasra.", "Tesniye ve cemdeki elif, vâv ve yâ, fetha, damme ve kesre gibi i'râbın kendisidir.",
    "They are letters of iʿrāb.", "Bunlar i'râb harfleridir."),
4: ("May a proper name ending in tāʾ take the sound masculine plural?", "Tâ ile biten müennes alem cem-i müzekker-i sâlimle toplanır mı?",
    "A name ending in the feminine tāʾ, given to a man, may take wāw and nūn: ṭalḥa, ṭalḥūn.", "Sonu te'nîs tâsı olan isim bir erkeğe ad olunca vâv-nûn ile toplanabilir: talha, talhûn.",
    "That is not allowed.", "Bu caiz değildir."),
5: ("What puts the mubtadaʾ and the khabar in rafʿ", "Mübtedâ ve haberi merfû kılan âmil",
    "Each raises the other: the mubtadaʾ the khabar and the khabar the mubtadaʾ.", "Mübtedâ haberi, haber mübtedâyı ref' eder; birbirlerini ref' ederler.",
    "The mubtadaʾ is raised by the ibtidāʾ; on the khabar they differ.", "Mübtedâ ibtidâ ile merfûdur; haberde ise ihtilâf etmişlerdir."),
6: ("What raises the noun after a ẓarf or jārr-majrūr", "Zarf ve câr-mecrûrdan sonraki ismin âmili",
    "A fronted ẓarf raises the noun (they call it maḥall or ṣifa): amāmaka Zaydun.", "Öne geçen zarf ismi ref' eder (ona mahal ya da sıfat derler): emâmeke Zeydün.",
    "The ẓarf does not raise it; the noun is raised by the ibtidāʾ.", "Zarf onu ref' etmez; isim ibtidâ ile merfûdur."),
7: ("Does a non-derived khabar carry the mubtadaʾ's pronoun?", "Câmid haber mübtedânın zamirini taşır mı?",
    "A khabar that is a plain noun holds a pronoun going back to the mubtadaʾ.", "Mahz isim olan haber, mübtedâya dönen bir zamir taşır.",
    "It holds no pronoun.", "Zamir taşımaz."),
8: ("Must the pronoun be made explicit when the adjective runs on another's subject?", "Vasıf sahibinden başkasına câri olunca zamir izhar edilir mi?",
    "The pronoun in the active participle need not be made explicit.", "İsm-i fâildeki zamirin izharı gerekmez.",
    "It must be made explicit (all agree it need not when it runs on its own subject).", "İzharı gerekir (kendi sahibine câri olunca gerekmediğinde ittifak vardır)."),
9: ("Fronting the khabar before the mubtadaʾ", "Haberin mübtedâya takdimi",
    "The khabar may not be fronted, whether a single word or a sentence.", "Haber, müfred de olsa cümle de olsa öne alınamaz.",
    "It may be fronted, single word or sentence.", "Müfred ve cümle hâlinde öne alınabilir."),
10: ("What raises the noun after lawlā", "Levlâ'dan sonraki merfû ismin âmili",
    "Lawlā itself raises the noun after it.", "İsmi levlâ'nın kendisi ref' eder.",
    "It is raised by the ibtidāʾ.", "İbtidâ ile merfûdur."),
11: ("What puts the object in naṣb", "Mef'ûlü nasbeden âmil",
    "The verb and the doer together put the object in naṣb.", "Mef'ûlü fiil ile fâil birlikte nasbeder.",
    "The verb alone governs both doer and object.", "Fâil ve mef'ûlde yalnız fiil amel eder."),
12: ("What puts the ishtighāl noun in naṣb", "İştiğal ismini nasbeden âmil",
    "In Zaydan ḍarabtuhu it is governed by the verb that falls on the hāʾ.", "Zeyden darabtuhû'da, hâya vâki olan fiil ile mansûbdur.",
    "It is governed by an implied verb: ḍarabtu Zaydan ḍarabtuhu.", "Takdir edilen bir fiil ile mansûbdur: darabtu Zeyden darabtuhû."),
13: ("Which of two verbs governs, in tanāzuʿ", "Tenâzu'da iki âmilden hangisi amele evlâdır",
    "Letting the first verb govern is better.", "Birinci fiile amel ettirmek evlâdır.",
    "Letting the second verb govern is better.", "İkinci fiile amel ettirmek evlâdır."),
14: ("Niʿma and biʾsa: verbs or nouns?", "Ni'me ve bi'se: fiil mi isim mi?",
    "Niʿma and biʾsa are nouns, mubtadaʾs.", "Ni'me ve bi'se mübtedâ olan iki isimdir.",
    "They are two past verbs that do not conjugate.", "Tasarruf etmeyen iki mâzî fiildir."),
15: ("Afʿala of wonder: noun or verb?", "Taaccüb kalıbı ef'ale: isim mi fiil mi?",
    "Afʿala in mā aḥsana Zaydan is a noun.", "Mâ ahsene Zeyden'deki ef'ale isimdir.",
    "It is a past verb.", "Mâzî bir fiildir."),
16: ("Wonder at white and black, of all colours", "Renklerden yalnız beyaz ve siyahtan taaccüb",
    "Mā afʿalahu may be used for white and black alone of the colours: mā abyaḍahu.", "Renklerden yalnız beyaz ve siyah için mâ ef'alehû kullanılabilir: mâ ebyadahû.",
    "It is not allowed for them, as for the other colours.", "Diğer renkler gibi bunlarda da caiz değildir."),
17: ("Fronting the khabar of mā zāla and its sisters before them", "Mâ zâle ve kardeşlerinin haberini onlara takdim",
    "The khabar of mā zāla and its like may be put before it.", "Mâ zâle ve benzerlerinin haberi ona takdim edilebilir.",
    "That is not allowed.", "Bu caiz değildir."),
18: ("Fronting the khabar of laysa before it", "Leyse'nin haberini ona takdim",
    "The khabar of laysa may not be put before it.", "Leyse'nin haberi ona takdim edilemez.",
    "It may be, as the khabar of kāna may.", "Kâne'nin haberi gibi takdim edilebilir."),
19: ("What puts the khabar after negating mā in naṣb", "Nâfiye mâ'dan sonraki haberi nasbeden âmil",
    "In the Ḥijāzī dialect mā does not govern the khabar; it is manṣūb by a dropped jarr particle.", "Hicaz lügatinde mâ habere amel etmez; haber, hazfedilen cer harfi sebebiyle mansûbdur.",
    "Mā governs the khabar; the khabar is manṣūb by it.", "Mâ habere amel eder; haber onunla mansûbdur."),
20: ("Fronting what the khabar of mā governs before mā", "Mâ'nın haberinin ma'mûlünü mâ'ya takdim",
    "Ṭaʿāmaka mā Zaydun ākilan is allowed.", "Taâmeke mâ Zeydün âkilen caizdir.",
    "It is not allowed.", "Caiz değildir."),
21: ("Fronting what the restricted verb governs", "Kasr edilen fiilin ma'mûlünü takdim",
    "Mā ṭaʿāmaka akala illā Zaydun is not allowed.", "Mâ taâmeke ekele illâ Zeydün caiz değildir.",
    "It is allowed.", "Caizdir."),
22: ("What raises the khabar after inna", "İnne'den sonra haberi ref' eden âmil",
    "Inna and its sisters do not raise the khabar.", "İnne ve kardeşleri haberi ref' etmez.",
    "They raise the khabar.", "Haberi ref' ederler."),
23: ("Joining a rafʿ noun to the ism of inna before the khabar", "Haber gelmeden inne'nin ismine merfû atıf",
    "One may join to the place of inna before the khabar is complete; then they differ.", "Haber tamamlanmadan inne'nin mahalline atıf caizdir; sonra ihtilâf etmişlerdir.",
    "Joining to the place before the khabar is complete is never allowed.", "Haber tamamlanmadan mahalle atıf hiçbir hâlde caiz değildir."),
24: ("Does lightened in govern the noun in naṣb?", "Muhaffef in ismi nasbeder mi?",
    "In lightened from inna does not put the noun in naṣb.", "İnne'den muhaffef in ismi nasbetmez.",
    "It governs.", "Amel eder."),
25: ("The lām of ibtidāʾ in the khabar of lākinna", "Lâkinne'nin haberinde ibtidâ lâmı",
    "The lām may enter the khabar of lākinna, as it enters the khabar of inna.", "Lâm, inne'nin haberine girdiği gibi lâkinne'nin haberine de girebilir.",
    "The lām may not enter the khabar of lākinna.", "Lâm lâkinne'nin haberine giremez."),
26: ("The first lām of laʿalla: added or radical?", "Lealle'nin ilk lâmı: zâid mi aslî mi?",
    "The first lām of laʿalla is radical.", "Lealle'deki ilk lâm aslîdir.",
    "It is added.", "Zâiddir."),
27: ("Fronting what an ism fiʿl governs", "İsm-i fiilin ma'mûlünü ona takdim",
    "In ighrāʾ, ʿalayka, dūnaka, ʿindaka may have what they govern put before them: Zaydan ʿalayka.", "İğrâda aleyke, dûneke, indeke'nin ma'mûlü öne alınabilir: Zeyden aleyke.",
    "What they govern may not be put before them.", "Ma'mûlleri onlara takdim edilemez."),
28: ("The root of derivation: the verb or the maṣdar?", "İştikakın aslı: fiil mi masdar mı?",
    "The maṣdar is derived from the verb and is its branch.", "Masdar fiilden türemiştir ve onun fer'idir.",
    "The verb is derived from the maṣdar and is its branch.", "Fiil masdardan türemiştir ve onun fer'idir."),
29: ("What puts a ẓarf that is the khabar in naṣb", "Haber olan zarfı nasbeden âmil",
    "The ẓarf as khabar is manṣūb by khilāf (difference): Zaydun amāmaka.", "Haber olan zarf hilâf ile mansûbdur: Zeydün emâmeke.",
    "It is manṣūb by an implied verb: Zaydun istaqarra amāmaka.", "Takdir edilen bir fiil ile mansûbdur: Zeydün istekarra emâmeke."),
30: ("What puts the mafʿūl maʿahu in naṣb", "Mef'ûlün meahı nasbeden âmil",
    "The mafʿūl maʿahu is manṣūb by khilāf: istawā al-māʾu wa-l-khashabata.", "Mef'ûlün meah hilâf ile mansûbdur: istevel-mâu vel-haşebete.",
    "It is manṣūb by the verb before it, through the wāw.", "Vâv vasıtasıyla, önündeki fiil ile mansûbdur."),
31: ("Fronting the ḥāl before the verb that governs it", "Hâli âmili olan fiile takdim",
    "The ḥāl may not precede its verb with an apparent noun (rākiban jāʾa Zaydun), but may with a pronoun (rākiban jiʾtu).", "Zâhir isimle hâl fiilinden önce gelemez (râkiben câe Zeydün), zamirle gelebilir (râkiben ci'tü).",
    "It may precede its verb with both the apparent noun and the pronoun.", "Zâhir isimle de zamirle de takdimi caizdir."),
32: ("Can a past verb be a ḥāl?", "Mâzî fiil hâl olur mu?",
    "A past verb may be a ḥāl.", "Mâzî fiil hâl olabilir.",
    "It may not (all agree it may with qad, or as the adjective of something dropped).", "Olamaz (kad ile ya da mahzûfun vasfı olunca olabileceğinde ittifak vardır)."),
33: ("The cases of a predicable adjective with a repeated ẓarf", "Tekrarlanan zarfla birlikte habere elverişli sıfatın i'râbı",
    "When the complete ẓarf that is the khabar is repeated, the adjective must be manṣūb: fī al-dāri Zaydun qāʾiman fīhā.", "Haber olan tam zarf tekrarlanınca sıfatın nasbı vâciptir: fid-dâri Zeydün kâimen fîhâ.",
    "Naṣb is not required; rafʿ is allowed as naṣb is.", "Nasb vâcip değildir; nasb gibi ref' de caizdir."),
34: ("What puts the mustathnā in naṣb", "Müstesnâyı nasbeden âmil",
    "The Kufans differ: some say illā governs it; al-Farrāʾ says illā is inna + lā; al-Kisāʾī is reported with two reasons.", "Kûfeliler ihtilâf etmiştir: bazısı âmil illâ'dır der; Ferrâ illâ'nın inne ile lâ'dan mürekkep olduğunu söyler; Kisâî'den iki sebep nakledilir.",
    "The governor is the verb, or the verb's meaning, through illā.", "Âmil, illâ vasıtasıyla fiil ya da fiil mânâsıdır."),
35: ("Can illā mean wa (and)?", "İllâ, vâv mânâsına gelir mi?",
    "Illā can mean the wāw.", "İllâ vâv mânâsında olabilir.",
    "It cannot.", "Olamaz."),
36: ("Fronting the particle of exception to the head of the sentence", "İstisnâ harfini kelâmın başına takdim",
    "The particle of exception may come first: illā ṭaʿāmaka mā akala Zaydun (al-Kisāʾī).", "İstisnâ harfi başa gelebilir: illâ taâmeke mâ ekele Zeydün (Kisâî bunu açıkça söyler).",
    "That is not allowed.", "Bu caiz değildir."),
37: ("Ḥāshā in exception: verb, particle, or both", "İstisnâda hâşâ: fiil mi, harf mi, ikisi mi?",
    "Ḥāshā in exception is a past verb.", "İstisnâdaki hâşâ mâzî fiildir.",
    "It is a jarr particle.", "Cer harfidir."),
38: ("May ghayr always be built?", "Gayr her yerde mebnî olur mu?",
    "Ghayr may be built on the fatḥa wherever illā fits, whatever it is annexed to.", "İllâ'nın yakıştığı her yerde gayr, neye muzâf olursa olsun, fetha üzere mebnî olabilir.",
    "It may be built only when annexed to an indeclinable word.", "Ancak mütemekkin olmayan bir kelimeye muzâf olunca mebnî olabilir."),
39: ("Siwā: a noun, or always a ẓarf?", "Sivâ: isim mi, daima zarf mı?",
    "Siwā is both a noun and a ẓarf.", "Sivâ hem isim hem zarf olur.",
    "It is only ever a ẓarf.", "Ancak zarf olur."),
40: ("Kam: compound or single?", "Kem: mürekkep mi müfred mi?",
    "Kam is a compound.", "Kem mürekkeptir.",
    "It is single, laid down for number.", "Aded için konulmuş müfred bir kelimedir."),
41: ("Separating declarative kam from its tamyīz: does the tamyīz stay majrūr?", "Haberî kem ile temyizi arasına girilince temyiz mecrûr kalır mı?",
    "Separated by a ẓarf or a jarr particle, the noun is still majrūr: kam ʿindaka rajulin.", "Zarf ya da cer harfiyle ayrılınca isim mecrûr olur: kem indeke racülin.",
    "Jarr is not allowed; it must be manṣūb.", "Cer caiz değildir; mansûb olması vâciptir."),
42: ("Annexing the units to the ten", "Neyyifin (birlerin) aşere'ye izâfesi",
    "The units may be annexed to the ten: khamsata ʿasharin.", "Birler on'a muzâf olabilir: hamsete aşerin.",
    "It is not allowed.", "Caiz değildir."),
43: ("The article on a compound number and its tamyīz", "Mürekkep adede ve temyizine harf-i ta'rîf",
    "One may say al-khamsata al-ʿashara dirhaman, and al-khamsata al-ʿashara al-dirhama.", "El-hamsete'l-aşere dirhemen ve el-hamsete'l-aşere'd-dirheme denebilir.",
    "The article may not enter the ʿashara or the dirham (all allow it on the khamsa alone).", "Harf-i ta'rîf aşere'ye ve dirheme giremez (yalnız hamse'ye girdiğinde ittifak vardır)."),
44: ("Annexing a compound number to its like", "Mürekkep adedi benzerine izâfe",
    "As printed: one may not say thālitha ʿashara thalāthata ʿashara.", "Basıldığı gibi: sâlise aşere selâsete aşere denemez.",
    "One may not say thālitha ʿashara thalāthata ʿashara.", "Sâlise aşere selâsete aşere denemez."),
45: ("The single proper-name munādā: declined or built?", "Müfred alem münâdâ: mu'reb mi mebnî mi?",
    "The single definite munādā is declined, in rafʿ, without tanwīn.", "Müfred ma'rife münâdâ mu'rebdir, tenvînsiz merfûdur.",
    "It is built on the ḍamma, its place naṣb, because it is an object.", "Damme üzere mebnîdir, mahalli nasbdır; çünkü mef'ûldür."),
46: ("Calling a noun that has al", "Harf-i ta'rîfli ismin nidâsı",
    "A noun with al may be called: yā al-rajulu.", "Elif-lâmlı isme nidâ caizdir: yâ er-racülü.",
    "It is not allowed.", "Caiz değildir."),
47: ("The mīm of allāhumma: a substitute for the vocative particle?", "Allâhümme'deki mîm nidâ harfinin ivazı mı?",
    "The doubled mīm of allāhumma is not a substitute for yā.", "Allâhümme'deki şeddeli mîm yâ'nın ivazı değildir.",
    "It is a substitute for yā; the hāʾ is built on the ḍamma as a munādā.", "Yâ'nın ivazıdır; hâ nidâ olduğu için damme üzere mebnîdir."),
48: ("Tarkhīm of the annexed noun at the end of the second term", "Muzâfı muzâfun ileyhin sonunu atarak terhîm",
    "Tarkhīm of the muḍāf is allowed, at the end of the second term: yā āla ʿāmi.", "Muzâfın terhîmi caizdir; terhîm muzâfun ileyhin sonunda olur: yâ âle âmi.",
    "Tarkhīm of the muḍāf is not allowed.", "Muzâfın terhîmi caiz değildir."),
49: ("Tarkhīm of a three-letter noun", "Üç harfli ismin terhîmi",
    "A three-letter noun may be shortened if its middle is voweled: yā ʿunu.", "Ortası harekeli üç harfli isim terhîm edilebilir: yâ unu.",
    "A three-letter noun may never be shortened.", "Üç harfli isim hiçbir hâlde terhîm edilmez."),
50: ("Tarkhīm of a four-letter noun whose third is quiescent", "Üçüncüsü sâkin dört harfliyi terhîm",
    "A noun with a quiescent letter before its last loses both: yā qima for qimaṭr.", "Sondan önceki harfi sâkin olan isimde ikisi birden atılır: kımatr için yâ kıme.",
    "Only the last letter is dropped.", "Yalnız son harf atılır."),
51: ("Nudba of an indefinite noun and of relatives", "Nekirenin ve ism-i mevsûlün nüdbesi",
    "Nudba of the indefinite and the relative nouns is allowed.", "Nekire ve mevsûl isimlerin nüdbesi caizdir.",
    "It is not allowed.", "Caiz değildir."),
52: ("Putting the sign of nudba on the adjective", "Nüdbe alâmetini sıfata getirmek",
    "The sign of nudba may go on the adjective: wā-Zaydu al-ẓarīfāh.", "Nüdbe alâmeti sıfata getirilebilir: vâ Zeydü'z-zarîfâh.",
    "It is not allowed.", "Caiz değildir."),
53: ("The single indefinite noun after lā: declined or built?", "Lâ'nın müfred nekire ismi: mu'reb mi mebnî mi?",
    "The noun negated by lā is declined, manṣūb by lā: lā rajula fī al-dār.", "Lâ ile nefyedilen müfred nekire mu'rebdir, lâ ile mansûbdur: lâ racüle fid-dâr.",
    "It is built on the fatḥa.", "Fetha üzere mebnîdir."),
54: ("Does min mark the start of a span of time?", "Min zamanda ibtidâ-i gaye için gelir mi?",
    "Min may be used for time and for place.", "Min zamanda da mekânda da kullanılır.",
    "It may not be used for time.", "Zamanda kullanılmaz."),
55: ("The wāw of rubba: does it govern the jarr?", "Rubbe vâvı ceri kendisi mi yapar?",
    "The wāw of rubba puts the indefinite noun in jarr by itself.", "Rubbe vâvı nekireyi bizzat cerreder.",
    "The wāw does not govern; the jarr is by an implied rubba.", "Vâv amel etmez; amel takdir edilen rubbe'nindir."),
56: ("The noun after mudh and mundhu", "Müz ve münzü'den sonraki ismin i'râbı",
    "When the noun after mudh and mundhu is in rafʿ, it is raised by an implied, dropped verb.", "Müz ve münzü'den sonraki isim merfû olunca mahzûf bir fiil takdiriyle merfûdur.",
    "They are nouns, mubtadaʾs with what follows as khabar; or jarr particles governing what follows.", "Bunlar mübtedâ isimlerdir, sonrakiler haberdir; ya da sonrakini cerreden harflerdir."),
57: ("Does the oath particle govern when dropped without a substitute?", "Kasem harfi ivazsız hazfedilince amel eder mi?",
    "Jarr in an oath with the jarr particle dropped and nothing in its place is allowed.", "Kasemde cer harfi ivazsız gizlenerek cer caizdir.",
    "Only with a substitute: the question alif, or hāʾ of alerting (hāllāhi).", "Ancak bir ivazla caizdir: istifham elifi ya da tenbîh hâsı (hâllâhi)."),
58: ("The lām on the mubtadaʾ: of ibtidāʾ, or the answer to an oath?", "Mübtedâya giren lâm: ibtidâ lâmı mı, kasem cevabı mı?",
    "The lām in la-Zaydun afḍalu min ʿAmrin answers an implied oath.", "Le-Zeydün efdalü min Amrin'deki lâm takdir edilen kasemin cevabıdır.",
    "It is the lām of ibtidāʾ.", "İbtidâ lâmıdır."),
59: ("Ayman in the oath: single or plural?", "Kasemde eymün: müfred mi cem mi?",
    "Ayman in ayman Allāh is the plural of yamīn.", "Eymunullâh'taki eymün yemîn'in cem'idir.",
    "It is not the plural of yamīn; it is a single noun derived from yumn.", "Yemîn'in cem'i değildir; yümn'den türemiş müfred bir isimdir."),
60: ("Separating the muḍāf from the muḍāf ilayh", "Muzâf ile muzâfun ileyhin arasını ayırmak",
    "They may be separated by other than a ẓarf or jarr particle, under the necessity of verse.", "Şiir zarureti için zarf ve cer harfinden başkasıyla ayrılabilir.",
    "Not by other than a ẓarf or jarr particle.", "Zarf ve cer harfinden başkasıyla ayrılamaz."),
61: ("Annexing a noun to one of the same meaning", "Bir ismi aynı mânâdaki isme izâfe",
    "A thing may be annexed to itself when the two words differ.", "Lafızlar farklı olunca bir şey kendisine izâfe edilebilir.",
    "It is not allowed.", "Caiz değildir."),
62: ("Kilā and kiltā: dual in form and meaning, or in meaning only?", "Kilâ ve kiltâ: lafzen ve mânen mi, yalnız mânen mi tesniye?",
    "Kilā and kiltā are dual in form and meaning; the alif is the dual's.", "Kilâ ve kiltâ lafzen ve mânen tesniyedir; elif tesniye elifidir.",
    "They are single in form and dual in meaning; the alif is like that of ʿaṣan.", "Lafzen müfred, mânen tesniyedir; elif asâ'daki elif gibidir."),
63: ("Semantic tawkīd of an indefinite noun", "Nekirenin mânevî tekidi",
    "Tawkīd of the indefinite by another word is allowed when it is a measured span: qaʿadtu yawman kullahu.", "Nekire belirli bir süre olunca başka lafızla tekidi caizdir: kaadtü yevmen küllehû.",
    "It is never allowed.", "Hiçbir hâlde caiz değildir."),
64: ("Can the conjoining wāw be redundant?", "Atıf vâvı zâid gelebilir mi?",
    "The conjoining wāw may be redundant.", "Atıf vâvı zâid olabilir.",
    "It may not.", "Olamaz."),
65: ("Conjoining to a majrūr pronoun", "Mecrûr zamire atıf",
    "As printed: conjoining to the majrūr pronoun «yajibu» (is required): marartu bika wa-Zaydin.", "Basıldığı gibi: mecrûr zamire atıf «yecibü» (vâciptir): merertü bike ve Zeydin.",
    "It is not allowed.", "Caiz değildir."),
66: ("Conjoining to an attached rafʿ pronoun in ordinary speech", "Muttasıl merfû zamire ihtiyârî kelâmda atıf",
    "It is allowed in ordinary speech: qumtu wa-Zaydun.", "İhtiyârî kelâmda caizdir: kumtü ve Zeydün.",
    "Only, and badly, under the necessity of verse.", "Ancak şiir zaruretinde, çirkin olarak caizdir."),
67: ("Does aw mean wa and bal?", "Ev, vâv ve bel mânâsına gelir mi?",
    "Aw can mean the wāw and can mean bal.", "Ev hem vâv hem bel mânâsına gelir.",
    "It means neither.", "İkisinin de mânâsına gelmez."),
68: ("Conjoining with lākin after an affirmative", "Müspet kelâmdan sonra lâkin ile atıf",
    "Conjoining with lākin after an affirmative is allowed: atānī Zaydun lākin ʿAmrun.", "Müspetten sonra lâkin ile atıf caizdir: etânî Zeydün lâkin Amrün.",
    "It is not; after an affirmative the clause after it must differ from the one before.", "Caiz değildir; müspetten sonra gelirse ardındaki cümle öncekine muhalif olmalıdır."),
69: ("Declining afʿal min under the necessity of verse", "Şiir zaruretinde ef'alü min'i munsarif kılmak",
    "Afʿalu minka may not be given tanwīn even under necessity.", "Ef'alü minke zaruret hâlinde de munsarif kılınamaz.",
    "It may be, under the necessity of verse.", "Şiir zaruretinde munsarif kılınabilir."),
70: ("Withholding tanwīn from a declinable noun in verse", "Şiirde munsarif ismi gayr-i munsarif kılmak",
    "A declinable noun may lose its tanwīn under the necessity of verse.", "Munsarif isim şiir zaruretinde gayr-i munsarif kılınabilir.",
    "It may not (all agree an indeclinable may take tanwīn in verse).", "Kılınamaz (gayr-i munsarifin şiirde munsarif kılınabileceğinde ittifak vardır)."),
71: ("Why al-āna is built", "El-âne'nin mebnî oluşunun illeti",
    "Al-āna is built because al entered the past verb āna, which kept its fatḥa.", "El-âne mebnîdir; çünkü elif-lâm âne (vakti geldi) mâzî fiiline girmiş, fiil fethasında kalmıştır.",
    "It is built because it resembles a demonstrative.", "İşaret ismine benzediği için mebnîdir."),
72: ("The imperative: declined or built?", "Emir fiili: mu'reb mi mebnî mi?",
    "The imperative without the prefix (ifʿal) is declined, majzūm.", "Muzâraat harfi olmayan emir (if'al) mu'rebdir, meczûmdur.",
    "It is built on the sukūn.", "Sükûn üzere mebnîdir."),
73: ("Why the muḍāriʿ is declined", "Muzârinin mu'reb oluşunun illeti",
    "It is declined because varied meanings and long times enter it.", "Ona farklı mânâlar ve uzun vakitler girdiği için mu'rebdir.",
    "It is declined for three reasons (the first given here: it is general, then specified, as a noun is).", "Üç sebepten mu'rebdir (burada ilki: isim gibi önce şâyi', sonra muhtas olur)."),
74: ("What raises the muḍāriʿ", "Muzâriyi ref' eden âmil",
    "The Kufans differ: most say it is raised by being free of the naṣb and jazm governors; al-Kisāʾī, by the prefix.", "Kûfeliler ihtilâf eder: çoğu, nasb ve cezm âmillerinden hâlî oluşla merfûdur der; Kisâî, başındaki zâid harfle.",
    "It is raised by standing in the place of a noun.", "İsmin yerinde durduğu için merfûdur."),
75: ("What puts the muḍāriʿ after the wāw of maʿiyya in naṣb", "Maiyyet vâvından sonra muzâriyi nasbeden âmil",
    "In lā taʾkul al-samaka wa-tashraba al-labana the verb is manṣūb by ṣarf.", "Lâ te'kül es-semeke ve teşrabe'l-lebene'de fiil sarf ile mansûbdur.",
    "It is manṣūb by an implied an.", "Takdir edilen en ile mansûbdur."),
76: ("What puts the muḍāriʿ after the fāʾ of cause in naṣb", "Sebebiyye fâsından sonra muzâriyi nasbeden âmil",
    "After the fāʾ answering the six things it is manṣūb by khilāf.", "Altı şeyin cevabındaki fâdan sonra hilâf ile mansûbdur.",
    "It is manṣūb by a hidden an.", "Gizli en ile mansûbdur."),
77: ("Does a dropped an govern without a substitute?", "Hazfedilen masdar en'i bedelsiz amel eder mi?",
    "Light an governs the muḍāriʿ in naṣb when dropped without a substitute (the print reads «al-Kūfiyyīn»).", "Hafif en, bedelsiz hazfedilince de muzâriyi nasbeder (baskıda «el-Kûfiyyîn» yazılı).",
    "It does not govern when dropped without a substitute.", "Bedelsiz hazfedilince amel etmez."),
78: ("Can kay be a jarr particle?", "Key cer harfi olabilir mi?",
    "Kay is only a particle of naṣb, never of jarr.", "Key ancak nasb harfidir, cer harfi olamaz.",
    "It can be a jarr particle.", "Cer harfi olabilir."),
79: ("What puts the muḍāriʿ after the lām of cause in naṣb", "Ta'lîl lâmından sonra muzâriyi nasbeden âmil",
    "The lām of kay itself puts the verb in naṣb, with no an implied: jiʾtuka li-tukrimanī.", "Fiili, en takdir edilmeden key lâmı kendisi nasbeder: ci'tüke li-tükrimenî.",
    "An implied an after it governs: li-an tukrimanī.", "Ondan sonra takdir edilen en nasbeder: li-en tükrimenî."),
80: ("May an appear after li-kay and after ḥattā?", "Likey'den ve hattâ'dan sonra en izhar edilir mi?",
    "An may appear after kay: jiʾtu li-kay an ukrimaka — kay governs, an confirms.", "Key'den sonra en izhar edilebilir: ci'tü li-key en ükrimeke — amel key'indir, en tekittir.",
    "An may never appear after any of them.", "Bunların hiçbirinden sonra en izhar edilemez."),
81: ("Can kamā mean kaymā and govern naṣb?", "Kemâ, keymâ mânâsına gelip nasbeder mi?",
    "Kamā can mean kaymā and they put what follows in naṣb, not forbidding rafʿ.", "Kemâ keymâ mânâsına gelir, sonrasını nasbederler, refi de men etmezler.",
    "Kamā does not mean kaymā, and naṣb after it is not allowed.", "Kemâ keymâ mânâsına gelmez; sonrasını onunla nasbetmek caiz değildir."),
82: ("Does the lām of juḥūd govern by itself? May its object come first?", "Cühûd lâmı bizzat nasbeder mi? Ma'mûlü öne geçer mi?",
    "The lām of juḥūd governs by itself; an may appear after it, and the verb's object may precede it.", "Cühûd lâmı bizzat nasbeder; ondan sonra en tekit için izhar edilebilir; fiilin mef'ûlü ona takdim edilebilir.",
    "An implied an governs; it may not appear, and the object may not precede the lām.", "Takdir edilen en nasbeder; izhar edilemez, mef'ûl lâma takdim edilemez."),
83: ("Does ḥattā govern the muḍāriʿ by itself?", "Hattâ muzâriyi bizzat nasbeder mi?",
    "Ḥattā governs the verb in naṣb with no an, and the noun in jarr with no implied jārr.", "Hattâ en takdirsiz fiili nasbeder, takdirsiz ismi cerreder.",
    "In both places it is a jarr particle; the verb is manṣūb by an implied an.", "Her iki yerde cer harfidir; fiil takdir edilen en ile mansûbdur."),
84: ("What puts the answer of the condition in jazm", "Şartın cevabını meczûm kılan âmil",
    "The answer of the condition is majzūm by proximity (jiwār).", "Şartın cevabı civâr ile meczûmdur.",
    "The Basrans differ: most say the particle of condition; others the particle and the verb; others the verb; al-Māzinī says it is built.", "Basralılar ihtilâf eder: çoğu şart harfi der; başkaları harf ile fiil; başkaları fiil; Mâzinî mebnî olduğunu söyler."),
85: ("What raises the noun after conditional in", "Şart in'inden sonraki merfû ismin âmili",
    "In in Zaydun atānī ātihi the noun is raised by the pronoun that returns to it in the verb, with no implied verb.", "İn Zeydün etânî âtihî'de isim, fiildeki ona dönen zamirle, fiil takdirsiz merfûdur.",
    "It is raised by an implied verb, which the expressed verb explains.", "Takdir edilen bir fiille merfûdur; zâhir fiil onu tefsir eder."),
86: ("Fronting a rafʿ or naṣb noun in the answer of the condition", "Şart cevabında merfû veya mansûb ismi öne almak",
    "With a rafʿ noun fronted in the answer, jazm is not allowed and rafʿ is required; on a fronted naṣb noun al-Farrāʾ and al-Kisāʾī differ.", "Cevapta merfû isim öne geçerse cezm caiz olmaz, ref' vâcip olur; mansûbun takdiminde Ferrâ ile Kisâî ihtilâf eder.",
    "Fronting both is allowed.", "İkisinin takdimi de caizdir."),
87: ("Fronting the object of the answer before the particle of condition", "Cezânın mef'ûlünü şart harfine takdim",
    "The object of the answer may come before the particle: Zaydan in taḍrib aḍrib; on its being governed by the condition they differ.", "Cezânın mef'ûlü şart harfinden önce gelebilir: Zeyden in tadrib adrib; şartla mansûb olmasında ihtilâf ederler.",
    "It may be governed neither by the condition nor by the answer.", "Ne şartla ne cezâ ile mansûb olabilir."),
88: ("Can conditional in mean idh?", "Şart in'i iz mânâsına gelir mi?",
    "Conditional in can mean idh.", "Şart in'i iz mânâsına gelir.",
    "It cannot.", "Gelmez."),
89: ("In after mā: negating, or redundant?", "Mâ'dan sonraki in: nâfiye mi zâide mi?",
    "In after mā (mā in Zaydun qāʾimun) means mā.", "Mâ'dan sonraki in (mâ in Zeydün kâimün) mâ mânâsındadır.",
    "It is redundant.", "Zâiddir."),
90: ("The meaning of in and of the lām after it", "İn'in ve ondan sonraki lâmın mânâsı",
    "In followed by the lām means mā, and the lām means illā.", "Arkasından lâm gelen in, mâ mânâsındadır; lâm illâ mânâsındadır.",
    "It is lightened from inna, and the lām is the lām of emphasis.", "İnne'den muhaffeftir; lâm tekit lâmıdır."),
91: ("Is kayfa used for the condition?", "Keyfe ile şart yapılır mı?",
    "Kayfa is used for the condition, like matā mā and aynamā.", "Keyfe ile, metâ mâ ve eynemâ gibi şart yapılır.",
    "It is not allowed.", "Caiz değildir."),
92: ("The sīn: cut from sawfa, or a root of its own?", "Sîn: sevfe'den kesilmiş mi, başlı başına asıl mı?",
    "The sīn of the future (saʾafʿalu) is originally sawfa.", "Gelecek sîni (seef'alü) aslında sevfe'dir.",
    "It is a root by itself.", "Başlı başına asıldır."),
93: ("Which of two initial tāʾs of the muḍāriʿ is dropped", "Muzâri başındaki iki tâdan hangisi düşer",
    "Of the tāʾ of the muḍāriʿ and a radical tāʾ, the muḍāriʿ's is dropped: tanāwalu.", "Muzâraat tâsı ile aslî tâdan muzâraat tâsı düşer: tenâvelü.",
    "The radical tāʾ is dropped, not that of the muḍāriʿ.", "Muzâraat tâsı değil aslî tâ düşer."),
94: ("The light nūn of emphasis on the dual and the feminine plural", "Hafif tekit nûnu tesniye ve cem-i müennes fiiline",
    "The light nūn may enter the verb of two and of women: ifʿalānn.", "Hafif nûn iki kişinin ve kadınlar topluluğunun fiiline girebilir: if'alânn.",
    "It may not, in these two places.", "Bu iki yerde giremez."),
95: ("The letters of the noun in dhā and alladhī", "Zâ ve ellezî'de ismin harfleri",
    "In dhā and alladhī the noun is the dhāl alone; the rest is added.", "Zâ ve ellezî'de isim yalnız zâldir; geri kalanı çoğaltmadır.",
    "The dhāl alone is not the noun; on dhā they differ.", "İsim yalnız zâl değildir; zâ hakkında ihtilâf etmişlerdir."),
96: ("The letters of the noun in huwa and hiya", "Hüve ve hiye'de ismin harfleri",
    "In huwa and hiya the noun is the hāʾ alone.", "Hüve ve hiye'de isim yalnız hâdır.",
    "The hāʾ with the wāw, and the hāʾ with the yāʾ, together are the noun.", "Hâ ile vâv ve hâ ile yâ, ikisi birlikte isimdir."),
97: ("Lawlāya and lawlāka: are they said, and in what case?", "Levlâye ve levlâke denir mi, zamirlerin mahalli ne?",
    "The yāʾ and kāf in lawlāya and lawlāka are in the place of rafʿ.", "Levlâye ve levlâke'deki yâ ve kâf ref' mahallindedir.",
    "They are in the place of jarr, governed by lawlā.", "Levlâ ile cer mahallindedir."),
98: ("The pronoun in iyyāka and its sisters", "İyyâke ve kardeşlerinde zamir",
    "The kāf, hāʾ and yāʾ of iyyāka are the naṣb pronouns; iyyā is a support (ʿimād).", "İyyâke'deki kâf, hâ ve yâ mansûb zamirlerdir; iyyâ imaddır.",
    "Iyyā is the pronoun; the kāf, hāʾ and yāʾ are particles with no place in iʿrāb.", "Zamir iyyâ'dır; kâf, hâ ve yâ i'râbda mahalli olmayan harflerdir."),
99: ("The question of the hornet (al-zunbūriyya)", "Zünbûriyye meselesi",
    "One may say: kuntu aẓunnu anna al-ʿaqraba ashaddu lasʿatan min al-zunbūri fa-idhā huwa iyyāhā.", "Küntü ezunnü enne'l-akrabe eşeddü les'aten mine'z-zünbûr fe-izâ hüve iyyâhâ denebilir.",
    "One may not say fa-idhā huwa iyyāhā.", "Fe-izâ hüve iyyâhâ denemez."),
100: ("The pronoun of separation", "Fasıl zamiri",
    "What separates the adjective from the khabar is called ʿimād and has a place in iʿrāb.", "Na't ile haberi ayıran şeye imad denir; i'râbda mahalli vardır.",
    "It is called faṣl, because it separates them, and has no place in iʿrāb.", "Ona fasl denir, çünkü ayırır; i'râbda mahalli yoktur."),
101: ("The ranks of the definite nouns", "Ma'rifelerin mertebeleri",
    "The demonstrative (hādhā) is more definite than the proper name (Zayd).", "İşaret ismi (hâzâ), alemden (Zeyd) daha ma'rifedir.",
    "The proper name is more definite than the demonstrative; on the ranks they differ.", "Alem işaret isminden daha ma'rifedir; mertebelerde ihtilâf etmişlerdir."),
102: ("Relative ayy: always declined, or sometimes built?", "Mevsûl eyy: daima mu'reb mi, bazen mebnî mi?",
    "Ayyuhum meaning alladhī, with the returner dropped, is declined: la-aḍribanna ayyuhum afḍalu.", "Ellezî mânâsındaki eyyühüm, âid hazfedilince mu'rebdir: le-adribenne eyyühüm efdalü.",
    "It is built on the ḍamma (all agree it is declined when the returner is said).", "Damme üzere mebnîdir (âid zikredilince mu'reb olduğunda ittifak vardır)."),
103: ("Can demonstratives be relatives?", "İşaret isimleri mevsûl olur mu?",
    "Hādhā and the other demonstratives can mean alladhī.", "Hâzâ ve diğer işaret isimleri ellezî mânâsında olabilir.",
    "They cannot mean alladhī or the relatives.", "Ellezî ve mevsûller mânâsında olamazlar."),
104: ("Can a noun with al have a ṣila like a relative?", "Elif-lâmlı isim mevsûl gibi sıla alır mı?",
    "An apparent noun with al takes a ṣila as alladhī does (the print reads «al-Kūfiyyīn»).", "Elif-lâmlı zâhir isim ellezî gibi sıla alır (baskıda «el-Kûfiyyîn» yazılı).",
    "It takes no ṣila.", "Sıla almaz."),
105: ("The hamza bayna bayna: voweled or quiescent?", "Beyne beyne hemzesi: harekeli mi sâkin mi?",
    "Hamza bayna bayna is quiescent.", "Beyne beyne hemzesi sâkindir.",
    "It is voweled.", "Harekelidir."),
106: ("Pausing on a manṣūb noun with al by moving the vowel back", "Elif-lâmlı mansûbda vakıfta harekeyi nakletmek",
    "In pause one may say raʾaytu al-bakar with a fatḥa on the kāf.", "Vakıfta kâfı fethalı olarak raeytü'l-bekar denebilir.",
    "It is not allowed.", "Caiz değildir."),
107: ("The original vowel of the hamzat al-waṣl", "Vasl hemzesinin aslî harekesi",
    "The hamzat al-waṣl follows the vowel of the verb's ʿayn: iḍrib, udkhul.", "Vasl hemzesi fiilin ayn harekesine tâbi olur: idrib, udhul.",
    "It is originally voweled with kasra, given ḍamma in udkhul to avoid kasra before ḍamma.", "Aslı kesreli harekedir; udhul'de kesreden dammeye geçmemek için dammelenir."),
108: ("Moving the vowel of the hamzat al-waṣl onto the quiescent letter before it", "Vasl hemzesinin harekesini önceki sâkine nakletmek",
    "It is allowed.", "Caizdir.",
    "It is not allowed.", "Caiz değildir."),
109: ("Lengthening the maqṣūr under the necessity of verse", "Şiir zaruretinde maksûru medletmek",
    "The maqṣūr may be lengthened under the necessity of verse.", "Şiir zaruretinde maksûr medlenebilir.",
    "It may not.", "Medlenemez."),
110: ("Dropping the end of a long maqṣūr or mamdūd in the dual", "Uzun maksûr ve memdûdun sonunu tesniyede atmak",
    "A long maqṣūr loses its alif in the dual (khawzalān), and a long mamdūd its last two letters.", "Harfleri çok olan maksûr tesniyede elifini düşürür (havzelân), uzun memdûd da son iki harfini.",
    "Nothing may be dropped, from maqṣūr or mamdūd.", "Ne maksûrdan ne memdûddan bir şey düşürülemez."),
111: ("Feminines without a sign, on the pattern of the active participle", "İsm-i fâil vezninde alâmetsiz müennesler",
    "The sign is dropped from ṭāliq, ḥāʾiḍ, ḥāmil because the meaning belongs to women alone.", "Tâlık, hâiz, hâmil'den alâmet, mânâ müennese mahsus olduğu için düşmüştür.",
    "It is dropped because they meant a relation (nasab), not a verb.", "Nisbet kastedildiği ve fiile câri kılınmadığı için düşmüştür."),
112: ("Why the wāw falls in yaʿidu", "Yaidü'de vâvın düşme sebebi",
    "The wāw of yaʿidu, yazinu falls to tell the intransitive from the transitive.", "Yaidü, yezinü'deki vâv, lâzım ile müteaddiyi ayırmak için düşmüştür.",
    "It falls because it stands between a yāʾ and a kasra.", "Yâ ile kesre arasında kaldığı için düşmüştür."),
113: ("The weight of a five-letter noun repeating its second and third", "İkinci ve üçüncüsü tekrarlanan beşlinin vezni",
    "Ṣamaḥmaḥ and damakmak weigh faʿallal.", "Samahmah ve demekmek fa'allal veznindedir.",
    "They weigh faʿalʿal.", "Fa'al'al veznindedir."),
114: ("Is every four- and five-letter noun augmented?", "Her dörtlü ve beşli isimde ziyade var mı?",
    "Every noun over three letters has an added letter; a four-letter one, one; on which one, they differ.", "Üç harften fazla her isimde ziyade vardır; dörtlüde bir harf; hangisi olduğunda ihtilâf ederler.",
    "Four- and five-letter roots are kinds apart from the three-letter; jaʿfar and safarjal have no added letter.", "Dörtlü ve beşliler üçlüden ayrı iki sınıftır; ca'fer ve sefercel'de ziyade yoktur."),
115: ("The weight of sayyid and mayyit", "Seyyid ve meyyit'in vezni",
    "Sayyid, hayyin, mayyit are originally faʿīl: sawīd, hawīn, mawīt.", "Seyyid, heyyin, meyyit aslında fa'îl veznindedir: sevîd, hevîn, mevît.",
    "Their weight is fayʿil, with kasra on the ʿayn.", "Vezinleri ayn'ı kesreli fey'ildir."),
116: ("The weight of khaṭāyā", "Hatâyâ'nın vezni",
    "Khaṭāyā, plural of khaṭīʾa, weighs faʿālī.", "Hatîe'nin cem'i hatâyâ, fe'âlî veznindedir.",
    "Khaṭāyā weighs faʿāʾil.", "Hatâyâ fe'âil veznindedir."),
117: ("The weight and root of insān", "İnsân'ın vezni ve iştikakı",
    "Insān weighs ifʿān.", "İnsân'ın vezni if'ân'dır.",
    "It weighs fiʿlān.", "Vezni fi'lân'dır."),
118: ("The weight of ashyāʾ", "Eşyâ'nın vezni",
    "Ashyāʾ weighs afʿāʾ, originally afʿilāʾ.", "Eşyâ'nın vezni ef'â'dır, aslı ef'ilâ'dır.",
    "It weighs lafʿāʾ, originally faʿlāʾ.", "Vezni lef'â'dır, aslı fa'lâ'dır."),
119: ("What puts the khabar of kāna and the second object of ẓanantu in naṣb", "Kâne'nin haberini ve zanentü'nün ikinci mef'ûlünü nasbeden",
    "They are manṣūb as ḥāl.", "Hâl olarak mansûbdurlar.",
    "They are manṣūb as objects, not as ḥāl.", "Hâl olarak değil, mef'ûl olarak mansûbdurlar."),
120: ("Fronting the tamyīz when its governor is a conjugating verb", "Âmili mutasarrıf fiil olunca temyizi öne almak",
    "The Kufans differ on fronting the tamyīz of a conjugating verb; some allow it, and al-Māzinī and al-Mubarrad agree.", "Kûfeliler mutasarrıf fiilin temyizini öne almada ihtilâf eder; bazısı caiz görür, Mâzinî ve Müberred de onlara katılır.",
    "Most Basrans: it is not allowed.", "Basralıların çoğu: caiz değildir."),
121: ("Rubba: noun or particle?", "Rubbe: isim mi harf mi?",
    "Rubba is a noun.", "Rubbe isimdir.",
    "It is a jarr particle.", "Cer harfidir."),
}
